import { Routes } from '@angular/router';
import { LoginComponent } from './features/auth/components/login/login';
import { HomeComponent } from './features/home/home';
import { SpaceDetailComponent } from './features/spaces/space-detail/space-detail';
import { MyBookingsComponent } from './features/bookings/my-bookings/my-bookings';
import { HostDashboardComponent } from './features/host/host-dashboard/host-dashboard';

export const routes: Routes = [
  {
    path: '',
    component: HomeComponent
  },
  {
    path: 'login',
    component: LoginComponent
  },
  {
    path: 'spaces/:id',
    component: SpaceDetailComponent
  },
  {
    path: 'my-bookings',
    component: MyBookingsComponent
  },
  {
    path: 'host/dashboard',
    component: HostDashboardComponent
  },
  {
    path: '**',
    redirectTo: '/'
  }
];

import { Routes } from '@angular/router';
import { LoginComponent } from './features/auth/components/login/login';
import { HomeComponent } from './features/home/home';
import { ExploreComponent } from './features/explore/explore';
import { SpaceDetailComponent } from './features/spaces/space-detail/space-detail';
import { MyBookingsComponent } from './features/bookings/my-bookings/my-bookings';
import { HostDashboardComponent } from './features/host/host-dashboard/host-dashboard';

export const routes: Routes = [
  {
    path: '',
    component: HomeComponent
  },
  {
    path: 'login',
    component: LoginComponent
  },
  {
    path: 'explore',
    component: ExploreComponent
  },
  {
    path: 'spaces',
    component: ExploreComponent
  },
  {
    path: 'spaces/:id',
    component: SpaceDetailComponent
  },
  {
    path: 'my-bookings',
    component: MyBookingsComponent
  },
  {
    path: 'host/dashboard',
    component: HostDashboardComponent
  },
  {
    path: '**',
    redirectTo: '/'
  }
];

/**
 * Explore/Search Page Styles
 */

.explore-page {
  min-height: 100vh;
  background: var(--gray-50);
}

/* Header Search Bar */
.explore-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: var(--space-6) 0;
  position: sticky;
  top: 0;
  z-index: 90;
}

.explore-search-bar {
  display: flex;
  gap: var(--space-2);
  background: var(--white);
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-2xl);
  padding: var(--space-2);
  box-shadow: var(--shadow-sm);
  align-items: stretch;
}

.search-input-group {
  flex: 1;
  padding: var(--space-3) var(--space-4);
  border-right: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  min-width: 0;
  transition: background var(--transition-fast);
}

.search-input-group:hover {
  background: var(--gray-50);
}

.search-input-group:last-of-type {
  border-right: none;
}

.search-input-label {
  font-size: var(--text-xs);
  font-weight: var(--font-bold);
  color: var(--gray-900);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: var(--space-1);
  margin-bottom: var(--space-2);
  letter-spacing: var(--tracking-wide);

  svg {
    color: var(--primary-600);
  }
}

.search-input {
  border: none;
  outline: none;
  font-size: var(--text-base);
  width: 100%;
  background: transparent;
  font-weight: var(--font-medium);
  color: var(--gray-900);

  &::placeholder {
    color: var(--gray-400);
    font-weight: var(--font-normal);
  }
}

.search-btn {
  flex-shrink: 0;
  padding: var(--space-4);
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  border: none;
  border-radius: var(--radius-xl);
  color: var(--white);
  cursor: pointer;
  transition: all var(--transition-base);
  display: flex;
  align-items: center;
  justify-content: center;

  &:hover {
    transform: scale(1.05);
    box-shadow: var(--shadow-primary);
  }
}

/* Content Layout */
.explore-content {
  padding: var(--space-8) 0;
}

.explore-layout {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: var(--space-8);
  align-items: start;
}

/* Sidebar Filters */
.explore-sidebar {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 150px;
  max-height: calc(100vh - 180px);
  overflow-y: auto;

  &.hidden {
    display: none;
  }
}

.filters-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-4);
  border-bottom: 1px solid var(--gray-200);

  h3 {
    font-size: var(--text-xl);
    font-weight: var(--font-bold);
    margin: 0;
  }
}

.filter-group {
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-6);
  border-bottom: 1px solid var(--gray-100);

  &:last-child {
    border-bottom: none;
  }
}

.filter-title {
  font-size: var(--text-sm);
  font-weight: var(--font-semibold);
  color: var(--gray-900);
  margin-bottom: var(--space-4);
}

.filter-inputs {
  display: flex;
  gap: var(--space-2);
  align-items: center;

  input {
    flex: 1;
  }

  span {
    color: var(--gray-500);
  }
}

.amenities-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-2);
}

.amenity-chip {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3);
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  cursor: pointer;
  transition: all var(--transition-fast);
  font-size: var(--text-sm);

  &:hover {
    background: var(--gray-100);
    border-color: var(--gray-300);
  }

  &.selected {
    background: var(--primary-50);
    border-color: var(--primary-600);
    color: var(--primary-700);
  }
}

.amenity-icon {
  font-size: var(--text-lg);
}

.amenity-label {
  font-weight: var(--font-medium);
}

/* Results */
.explore-results {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-sm);
  min-height: 600px;
}

.results-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-4);
  border-bottom: 1px solid var(--gray-200);
}

.results-info {
  p {
    margin: 0;
    font-size: var(--text-base);
    color: var(--gray-700);

    strong {
      color: var(--gray-900);
    }
  }
}

.toolbar-actions {
  display: flex;
  gap: var(--space-3);
  align-items: center;
}

.sort-dropdown {
  select {
    padding: var(--space-2) var(--space-4);
    border: 1px solid var(--gray-300);
    border-radius: var(--radius-lg);
    font-size: var(--text-sm);
    background: var(--white);
    cursor: pointer;

    &:focus {
      outline: none;
      border-color: var(--primary-600);
    }
  }
}

/* Results Grid */
.results-grid {
  &.grid-view {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: var(--space-6);
  }

  &.list-view {
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
  }
}

.load-more {
  text-align: center;
  margin-top: var(--space-8);
}

/* Responsive */
@media (max-width: 1023px) {
  .explore-layout {
    grid-template-columns: 1fr;
  }

  .explore-sidebar {
    position: static;
    max-height: none;
  }

  .results-grid.grid-view {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 767px) {
  .explore-header {
    padding: var(--space-4) 0;
  }

  .explore-search-bar {
    flex-direction: column;
  }

  .search-input-group {
    border-right: none;
    border-bottom: 1px solid var(--gray-200);

    &:last-of-type {
      border-bottom: none;
    }
  }

  .search-btn {
    width: 100%;
  }

  .explore-content {
    padding: var(--space-4) 0;
  }

  .explore-sidebar {
    padding: var(--space-4);
  }

  .explore-results {
    padding: var(--space-4);
  }

  .results-toolbar {
    flex-direction: column;
    gap: var(--space-3);
    align-items: stretch;
  }

  .toolbar-actions {
    justify-content: space-between;
  }

  .results-grid.grid-view {
    grid-template-columns: 1fr;
  }

  .amenities-grid {
    grid-template-columns: 1fr;
  }
}

import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { SpacesService, Space } from '../../core/services/spaces.service';
import { SpaceCardComponent } from '../../shared/components/space-card/space-card';
import { SkeletonListComponent } from '../../shared/components/skeleton-list/skeleton-list';
import { EmptyStateComponent } from '../../shared/components/empty-state/empty-state';
import { SpaceFilters } from '../../core/models/filter.model';

/**
 * Explore/Search Page Component
 * Página de búsqueda y exploración de espacios con mapa y filtros
 */
@Component({
  selector: 'app-explore',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    SpaceCardComponent,
    SkeletonListComponent,
    EmptyStateComponent
  ],
  templateUrl: './explore.html',
  styleUrl: './explore.scss'
})
export class ExploreComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private spacesService = inject(SpacesService);

  // State
  loading = false;
  spaces: Space[] = [];
  error: string | null = null;

  // View mode
  viewMode: 'grid' | 'list' = 'grid';
  showFilters = true;

  // Filters
  filters: SpaceFilters = {
    price: { min: undefined, max: undefined },
    capacity: { min: undefined, max: undefined },
    amenities: []
  };

  // Search params
  searchLocation = '';
  searchDate = '';
  searchCapacity: number | null = null;

  // Sorting
  sortBy: 'distance' | 'price' | 'rating' = 'distance';
  sortOrder: 'asc' | 'desc' = 'asc';

  // Pagination
  currentPage = 1;
  pageSize = 20;
  hasMore = true;

  // Amenities options
  amenitiesOptions = [
    { value: 'wifi', label: 'WiFi', icon: '' },
    { value: 'parking', label: 'Parking', icon: '️' },
    { value: 'terraza', label: 'Terraza', icon: '️' },
    { value: 'cocina', label: 'Cocina', icon: '' },
    { value: 'barbacoa', label: 'Barbacoa', icon: '' },
    { value: 'piscina', label: 'Piscina', icon: '' },
    { value: 'aire_acondicionado', label: 'Aire Acondicionado', icon: '❄️' },
    { value: 'musica', label: 'Sistema de Música', icon: '' }
  ];

  ngOnInit(): void {
    // Get query params from URL
    this.route.queryParams.subscribe(params => {
      this.searchLocation = params['location'] || '';
      this.searchDate = params['date'] || '';
      this.searchCapacity = params['capacity'] ? Number(params['capacity']) : null;

      // Initialize filters from params
      if (params['minPrice']) this.filters.price!.min = Number(params['minPrice']);
      if (params['maxPrice']) this.filters.price!.max = Number(params['maxPrice']);
      if (params['minCapacity']) this.filters.capacity!.min = Number(params['minCapacity']);

      this.loadSpaces();
    });
  }

  loadSpaces(): void {
    this.loading = true;
    this.error = null;

    // For now, load all active spaces
    // TODO: Implement actual search/filter API
    this.spacesService.getActiveSpaces().subscribe({
      next: (spaces) => {
        this.spaces = this.filterSpaces(spaces);
        this.loading = false;
      },
      error: (error) => {
        console.error('❌ Error loading spaces:', error);
        this.error = 'No se pudieron cargar los espacios';
        this.loading = false;
      }
    });
  }

  filterSpaces(spaces: Space[]): Space[] {
    let filtered = [...spaces];

    // Filter by capacity
    if (this.searchCapacity) {
      filtered = filtered.filter(s => s.capacity >= this.searchCapacity!);
    }

    if (this.filters.capacity?.min) {
      filtered = filtered.filter(s => s.capacity >= this.filters.capacity!.min!);
    }

    // Filter by price
    if (this.filters.price?.min) {
      filtered = filtered.filter(s => s.basePriceCents >= this.filters.price!.min! * 100);
    }

    if (this.filters.price?.max) {
      filtered = filtered.filter(s => s.basePriceCents <= this.filters.price!.max! * 100);
    }

    // Filter by amenities
    if (this.filters.amenities && this.filters.amenities.length > 0) {
      filtered = filtered.filter(space => {
        if (!space.amenities) return false;
        return this.filters.amenities!.some(amenity =>
          space.amenities!.includes(amenity)
        );
      });
    }

    // Sort
    filtered = this.sortSpaces(filtered);

    return filtered;
  }

  sortSpaces(spaces: Space[]): Space[] {
    return spaces.sort((a, b) => {
      let comparison = 0;

      switch (this.sortBy) {
        case 'price':
          comparison = a.basePriceCents - b.basePriceCents;
          break;
        case 'distance':
          // TODO: Calculate actual distance
          comparison = 0;
          break;
        case 'rating':
          // TODO: Implement rating
          comparison = 0;
          break;
      }

      return this.sortOrder === 'asc' ? comparison : -comparison;
    });
  }

  applyFilters(): void {
    this.currentPage = 1;
    this.loadSpaces();
  }

  clearFilters(): void {
    this.filters = {
      price: {},
      capacity: {},
      amenities: []
    };
    this.searchCapacity = null;
    this.currentPage = 1;
    this.loadSpaces();
  }

  toggleAmenity(amenity: string): void {
    if (!this.filters.amenities) {
      this.filters.amenities = [];
    }

    const index = this.filters.amenities.indexOf(amenity);
    if (index > -1) {
      this.filters.amenities.splice(index, 1);
    } else {
      this.filters.amenities.push(amenity);
    }

    this.applyFilters();
  }

  isAmenitySelected(amenity: string): boolean {
    return this.filters.amenities?.includes(amenity) || false;
  }

  changeSortBy(sortBy: 'distance' | 'price' | 'rating'): void {
    if (this.sortBy === sortBy) {
      // Toggle order
      this.sortOrder = this.sortOrder === 'asc' ? 'desc' : 'asc';
    } else {
      this.sortBy = sortBy;
      this.sortOrder = 'asc';
    }
    this.applyFilters();
  }

  toggleViewMode(): void {
    this.viewMode = this.viewMode === 'grid' ? 'list' : 'grid';
  }

  toggleFilters(): void {
    this.showFilters = !this.showFilters;
  }

  viewSpace(space: Space): void {
    this.router.navigate(['/spaces', space.id]);
  }

  loadMore(): void {
    // TODO: Implement pagination
    this.currentPage++;
  }
}

/* ============================================
   BALCONAZO APP - DESIGN SYSTEM
   Professional design system with tokens
   ============================================ */

/* Import design tokens, utilities, and animations */
@use 'styles/tokens';
@use 'styles/utilities';
@use 'styles/animations';

/* ========== GLOBAL RESET ========== */

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  font-weight: var(--font-normal);
  line-height: var(--leading-normal);
  color: var(--gray-900);
  background-color: var(--white);
  overflow-x: hidden;
}

/* ========== TYPOGRAPHY ========== */

h1, h2, h3, h4, h5, h6 {
  font-weight: var(--font-bold);
  line-height: var(--leading-tight);
  margin-bottom: var(--space-4);
  color: var(--gray-900);
}

h1 { font-size: var(--text-4xl); }
h2 { font-size: var(--text-3xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }
h5 { font-size: var(--text-lg); }
h6 { font-size: var(--text-base); }

p {
  margin-bottom: var(--space-4);
  color: var(--gray-700);
}

a {
  color: var(--primary-600);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--primary-700);
}

a:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

strong, b {
  font-weight: var(--font-semibold);
}

small {
  font-size: var(--text-sm);
}

/* ========== BUTTONS ========== */

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  font-size: inherit;
}

button:disabled {
  opacity: var(--opacity-disabled);
  cursor: not-allowed;
}

button:focus-visible {
  outline: 2px solid var(--primary-600);
  outline-offset: 2px;
}

/* ========== FORMS ========== */

input, textarea, select {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  color: inherit;
}

input:focus, textarea:focus, select:focus {
  outline: none;
}

label {
  display: block;
  font-weight: var(--font-medium);
  margin-bottom: var(--space-2);
  color: var(--gray-700);
}

/* ========== IMAGES ========== */

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ========== LAYOUT CONTAINERS ========== */

.container {
  width: 100%;
  max-width: var(--container-xl);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

@media (max-width: 640px) {
  .container {
    padding: 0 var(--space-4);
  }
}

/* ========== COMPONENT STYLES (legacy from existing app, kept for compatibility) ========== */

/* Navbar - will be replaced by new Navbar component in PR#4 */
.navbar {
  position: sticky;
  top: 0;
  height: var(--navbar-height);
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--gray-200);
  z-index: var(--z-sticky);
  transition: all var(--transition-base);
}

.navbar-container {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.navbar-logo {
  font-size: var(--text-2xl);
  font-weight: var(--font-extrabold);
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: var(--tracking-tight);
}

.navbar-menu {
  display: flex;
  gap: var(--space-8);
  list-style: none;
  margin: 0;
}

.navbar-link {
  color: var(--gray-700);
  font-weight: var(--font-medium);
  transition: color var(--transition-fast);
  padding: var(--space-2) 0;
  position: relative;
}

.navbar-link:hover {
  color: var(--primary-600);
}

.navbar-link.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary-600);
  border-radius: var(--radius-full);
}

/* Buttons - Enhanced */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-weight: var(--font-semibold);
  font-size: var(--text-base);
  border-radius: var(--radius-lg);
  min-height: 44px;
  border: none;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.btn:disabled {
  opacity: var(--opacity-disabled);
  cursor: not-allowed;
  transform: none !important;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary-600), var(--primary-500));
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover:not(:disabled) {
  box-shadow: var(--shadow-primary);
  transform: translateY(-2px);
}

.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}

.btn-secondary {
  background: var(--gray-100);
  color: var(--gray-900);
  border: 1px solid var(--gray-300);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--gray-200);
  border-color: var(--gray-400);
}

.btn-ghost {
  background: transparent;
  color: var(--gray-700);
}

.btn-ghost:hover:not(:disabled) {
  background: var(--gray-100);
}

.btn-danger {
  background: var(--error);
  color: var(--white);
}

.btn-danger:hover:not(:disabled) {
  background: var(--error-dark);
}

.btn-success {
  background: var(--success);
  color: var(--white);
}

.btn-success:hover:not(:disabled) {
  background: var(--success-dark);
}

.btn-lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-lg);
  min-height: 52px;
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm);
  min-height: 36px;
}

.btn-icon {
  padding: var(--space-3);
  min-height: 44px;
  width: 44px;
}

/* Hero Section */
.hero {
  min-height: 600px;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--gray-50) 100%);
  padding: var(--space-20) 0;
  position: relative;
}

.hero-content {
  text-align: center;
  max-width: 850px;
  margin: 0 auto;
}

.hero-title {
  font-size: var(--text-5xl);
  margin-bottom: var(--space-6);
  line-height: var(--leading-tight);
}

.hero-subtitle {
  font-size: var(--text-xl);
  color: var(--gray-600);
  margin-bottom: var(--space-8);
  line-height: var(--leading-relaxed);
}

/* Search Bar */
.search-bar {
  background: var(--white);
  border-radius: var(--radius-2xl);
  box-shadow: var(--shadow-xl);
  padding: var(--space-2);
  display: flex;
  gap: var(--space-2);
